<span class="line"><span style="color:#C678DD;">    private</span><span style="color:#E5C07B;"> EventHandler</span><span style="color:#ABB2BF;">? </span><span style="color:#E06C75;">_clicked</span><span style="color:#ABB2BF;">;</span></span>
